import { getLogger } from '~/lib/log';
import { events } from '~/lib/events';

export default function megamenu() {
  const log = getLogger(this.$id('megamenu'));

  return {
    /**
     * State
     */
    isOpen: false,
    isTouchDevice: 'ontouchstart' in window || navigator.maxTouchPoints > 0,

    /**
     * Lifecycle Methods
     */
    init() {
      log.debug('Megamenu component initialized');

      // Listen for header events to close megamenu when needed
      this.$el.addEventListener(events.header.closeAll, () => {
        this.closeMegamenu();
      });

      // Listen for mobile menu events to close megamenu
      this.$el.addEventListener(events.header.mobileMenuOpened, () => {
        this.closeMegamenu();
      });
    },

    destroy() {
      log.debug('Megamenu component destroyed');
    },

    /**
     * Instance Methods
     */
    openMegamenu() {
      if (!this.isOpen) {
        this.isOpen = true;
        // Dispatch event to close other megamenus
        this.$dispatch(events.megamenu.opened, { element: this.$el });
        log.debug('openMegamenu');
      }
    },

    closeMegamenu() {
      if (this.isOpen) {
        this.isOpen = false;
        this.$dispatch(events.megamenu.closed, { element: this.$el });
        log.debug('closeMegamenu');
      }
    },

    toggleMegamenu() {
      if (this.isOpen) {
        this.closeMegamenu();
      } else {
        this.openMegamenu();
      }
    },

    /**
     * Event Handlers
     */
    handleMouseEnter() {
      // Only handle hover on non-touch devices
      if (!this.isTouchDevice) {
        this.openMegamenu();
      }
    },

    handleMouseLeave() {
      // Only handle hover on non-touch devices
      if (!this.isTouchDevice) {
        this.closeMegamenu();
      }
    },

    handleLinkClick(event) {
      // For touch devices, prevent navigation on first click and open menu
      if (this.isTouchDevice && !this.isOpen) {
        event.preventDefault();
        this.openMegamenu();
      }
      // Second click on touch devices will allow normal navigation
    },

    handleClickAway() {
      this.closeMegamenu();
    },

    handleEscape(event) {
      if (event.key === 'Escape') {
        this.closeMegamenu();
      }
    },

    handleBlockSelect(event) {
      log.debug('Megamenu block selected in theme editor', { event });

      // Show megamenu when its block is selected in theme editor
      if (event.detail && event.detail.blockId) {
        this.isOpen = true;
        log.debug('Megamenu opened for theme editor block selection', { blockId: event.detail.blockId });
      }
    },

    handleBlockDeselect(event) {
      log.debug('Megamenu block deselected in theme editor', { event });

      // Hide megamenu when block is deselected in theme editor
      if (event.detail && event.detail.blockId) {
        this.isOpen = false;
        log.debug('Megamenu closed for theme editor block deselection', { blockId: event.detail.blockId });
      }
    },

    /**
     * Computed Properties
     */
    get megamenuClasses() {
      return {
        open: this.isOpen,
      };
    },

    /**
     * Alpine.js Directives
     */
    directives: {
      self: {
        '@mouseleave'() {
          this.handleMouseLeave();
        },
        '@click.away'() {
          this.handleClickAway();
        },
        '@keydown.escape'(event) {
          this.handleEscape(event);
        },
        [`@${events.shopify.blockSelect}`](event) {
          this.handleBlockSelect(event);
        },
        [`@${events.shopify.blockDeselect}`](event) {
          this.handleBlockDeselect(event);
        },
      },
      menuLink: {
        '@click'(event) {
          this.handleLinkClick(event);
        },
        '@mouseenter'() {
          this.handleMouseEnter();
        },
      },
      menuTrigger: {
        '@click'() {
          this.toggleMegamenu();
        },
      },
      menuBackButton: {
        '@click'() {
          this.closeMegamenu();
        },
      },
      flyout: {
        'x-show'() {
          return this.isOpen;
        },
        'x-transition:enter'() {
          return 'transition ease-out duration-200';
        },
        'x-transition:enter-start'() {
          return 'opacity-0 transform scale-95';
        },
        'x-transition:enter-end'() {
          return 'opacity-100 transform scale-100';
        },
        'x-transition:leave'() {
          return 'transition ease-in duration-150';
        },
        'x-transition:leave-start'() {
          return 'opacity-100 transform scale-100';
        },
        'x-transition:leave-end'() {
          return 'opacity-0 transform scale-95';
        },
      },
    },
  };
}
